const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Embeds the JavaScript bundle into debug APKs.
 *
 * By default a debug build ships no JS at all: at launch it tries to pull the
 * bundle from the Metro dev server on localhost:8081. That is fine on a
 * developer's machine and useless for a downloadable test APK — on a phone the
 * fetch fails, React never mounts, and the app sits on the splash screen
 * forever with no error. That is exactly what happened here.
 *
 * `bundleInDebug = true` makes the debug build run `expo export:embed` and pack
 * the bundle like a release build does, while keeping everything that makes a
 * debug build worth shipping to a tester:
 *   - no R8/ProGuard, so nothing is stripped or renamed;
 *   - the red error overlay, so a JS exception is shown ON SCREEN with a stack
 *     instead of killing the process with "uygulama sürekli olarak duruyor".
 *
 * android/ is generated by `expo prebuild` and gitignored, so this has to be a
 * config plugin — editing build.gradle by hand would not survive a build.
 */
module.exports = function withBundleInDebug(config) {
  return withAppBuildGradle(config, (cfg) => {
    const contents = cfg.modResults.contents;

    if (contents.includes('bundleInDebug')) return cfg;

    const anchor = 'react {';
    const index = contents.indexOf(anchor);
    if (index === -1) {
      throw new Error(
        'withBundleInDebug: `react {` blogu app/build.gradle icinde bulunamadi. ' +
          'Expo sablonu degismis olabilir; eklenti guncellenmeli.',
      );
    }

    const insertAt = index + anchor.length;
    cfg.modResults.contents =
      contents.slice(0, insertAt) +
      '\n    // Indirilebilir test APK\'si icin JS paketi APK\'ya gomulur;' +
      '\n    // aksi halde uygulama Metro sunucusunu arar ve splash ekraninda kalir.' +
      '\n    bundleInDebug = true' +
      contents.slice(insertAt);

    return cfg;
  });
};
